+        // 6×100ms 串行 = 600ms；并行两波 ≈ 200ms（阈值 500ms 留 CI 余量）
+        Assert.True(sw.ElapsedMilliseconds < 500, $"被串行化: {sw.ElapsedMilliseconds}ms");
