  9	namespace DesktopPet.App.Windows;
 10	
 11	/// <summary>
 12	/// 初始化引导窗（参考 harness/openclaw 的首次引导：先问称呼 + 选人格，之后设置页可改）。
 13	/// 架构：纯 UI 组件——不直接读/写存储，输入通过 <see cref="OnComplete"/> 回调交给调用方
 14	/// （App 启动 / 设置页开启 AI 两处触发，保存逻辑收敛到调用方一处）。
 15	/// Lumen 2.0：品牌头部 + 表单分组 + 主按钮。
 16	/// </summary>
 17	public sealed class WelcomeWindow : Window
 18	{
 19	    private readonly TextBox _callNameBox = new()
 20	    {
 21	        FontSize = 13,
 22	        Height = 34,
 23	        Padding = new Thickness(10, 4, 10, 4),
 24	        MaxLength = 20,
 25	    };
 26	    private readonly ComboBox _personaCombo = new() { FontSize = 13, Height = 34 };
 27	    private readonly IReadOnlyList<Persona> _builtinPersonas;
 28	    private readonly I18nService _i18n;
 29	
 30	    public WelcomeWindow(
 31	        IReadOnlyList<Persona> builtinPersonas,
 32	        string initialCallName,
 33	        string selectedPersonaId,
 34	        Func<string, string, bool> onComplete,
 35	        I18nService? i18n = null)
 36	    {
 37	        var localization = i18n ?? new I18nService();
 38	        _i18n = localization;
 39	        _builtinPersonas = builtinPersonas;
 40	        Title = "欢迎使用 AI 桌宠";
 41	        Width = 440;
 42	        Height = 390;
 43	        WindowStartupLocation = WindowStartupLocation.CenterScreen;
 44	        Background = (Brush)Application.Current.FindResource("WindowBgBrush");
 45	        ResizeMode = ResizeMode.NoResize;
 46	        ShowInTaskbar = false;
 47	
 48	        foreach (var p in builtinPersonas)
 49	        {
 50	            _personaCombo.Items.Add($"{_i18n.T(p.Name)} — {_i18n.T(p.Description)}");
 51	        }
 52	        var index = builtinPersonas.ToList().FindIndex(p => p.Id == selectedPersonaId);
 53	        _personaCombo.SelectedIndex = index >= 0 ? index : 0;
 54	
 55	        _callNameBox.Text = initialCallName;
 56	        _callNameBox.SelectAll();
