 69	            Child = new TextBlock
 70	            {
 71	                Text = "DP",
 72	                FontSize = 14,
 73	                FontWeight = FontWeights.Bold,
 74	                Foreground = (Brush)Application.Current.FindResource("AccentBrush"),
 75	                HorizontalAlignment = HorizontalAlignment.Center,
 76	                VerticalAlignment = VerticalAlignment.Center,
 77	            },
 78	        });
 79	        hero.Children.Add(new TextBlock
 80	        {
 81	            Text = "欢迎来到 DesktopPet",
 82	            FontSize = 20,
 83	            FontWeight = FontWeights.SemiBold,
 84	            Foreground = (Brush)Application.Current.FindResource("TextPrimaryBrush"),
 85	            HorizontalAlignment = HorizontalAlignment.Center,
 86	            Margin = new Thickness(0, 8, 0, 0),
 87	        });
 88	        hero.Children.Add(new TextBlock
 89	        {
 90	            Text = "先认识一下，之后随时可在 设置 → AI 助手 修改。",
 91	            FontSize = 12,
 92	            Foreground = (Brush)Application.Current.FindResource("TextTertiaryBrush"),
 93	            HorizontalAlignment = HorizontalAlignment.Center,
 94	            Margin = new Thickness(0, 4, 0, 0),
 95	        });
 96	        root.Children.Add(hero);
 97	
 98	        // 表单分组
 99	        var formCard = new Border
100	        {
101	            Background = (Brush)Application.Current.FindResource("CardBgBrush"),
102	            BorderBrush = (Brush)Application.Current.FindResource("StrokeBrush"),
103	            BorderThickness = new Thickness(1),
104	            CornerRadius = (CornerRadius)Application.Current.FindResource("RadiusCard"),
105	            Padding = new Thickness(18, 16, 18, 16),
106	            Effect = (Effect)Application.Current.FindResource("ShadowCard"),
107	        };
108	        var form = new StackPanel();
109	        form.Children.Add(new TextBlock
110	        {
111	            Text = "怎么称呼你？",
112	            FontSize = 12,
113	            Foreground = (Brush)Application.Current.FindResource("TextSecondaryBrush"),
114	            Margin = new Thickness(0, 0, 0, 6),
115	        });
116	        form.Children.Add(_callNameBox);
117	        form.Children.Add(new TextBlock
118	        {
119	            Text = "选一个它的人格（决定说话风格）：",
120	            FontSize = 12,
121	            Foreground = (Brush)Application.Current.FindResource("TextSecondaryBrush"),
122	            Margin = new Thickness(0, 14, 0, 6),
123	        });
124	        form.Children.Add(_personaCombo);
125	        formCard.Child = form;
126	        root.Children.Add(formCard);
127	
128	        var startButton = new Button
129	        {
130	            Content = "开始！",
131	            Style = (Style)Application.Current.FindResource("ButtonPrimaryStyle"),
132	            Width = 140,
133	            Height = 36,
134	            FontSize = 14,
135	            Margin = new Thickness(0, 18, 0, 0),
136	            HorizontalAlignment = HorizontalAlignment.Right,
137	        };
138	        startButton.Click += (_, _) =>
139	        {
140	            var callName = _callNameBox.Text.Trim();
141	            if (callName.Length == 0)
142	            {
143	                MessageBox.Show(this, _i18n.T("先告诉我怎么称呼你吧～"), "DesktopPet");
144	                return;
145	            }
146	            var personaId = builtinPersonas[Math.Max(0, _personaCombo.SelectedIndex)].Id;
147	            if (onComplete(callName, personaId))
148	                Close();
