150	        root.Children.Add(startButton);
151	        root.Children.Add(new TextBlock
152	        {
153	            Text = "称呼会存在记忆里（可改），人格随时可换。",
154	            FontSize = 10.5,
155	            Foreground = (Brush)Application.Current.FindResource("TextTertiaryBrush"),
156	            Margin = new Thickness(0, 8, 0, 0),
