165	    {
166	        var selected = _personaCombo.SelectedIndex;
167	        _personaCombo.Items.Clear();
168	        foreach (var persona in _builtinPersonas)
169	        {
170	            _personaCombo.Items.Add($"{i18n.T(persona.Name)} — {i18n.T(persona.Description)}");
171	        }
172	        _personaCombo.SelectedIndex = selected;
173	        WpfLocalizer.RefreshTracked(this, i18n);
174	    }
