 10	namespace DesktopPet.App.Windows;
 11	
 12	/// <summary>
 13	/// 导入切片预览（对齐 settings.html 的切片预览交互，最小版）：
 14	/// 原图 + 切片网格线覆盖 + 帧条（每行首帧缩略图），确认后导入。
 15	/// </summary>
 16	public sealed class SpritePreviewWindow : Window
 17	{
 18	    private readonly SpriteSheet _sheet;
 19	    private readonly byte[] _sourceBytes;
 20	    private readonly string _suggestedName;
 21	    private I18nService _i18n;
 22	    private readonly TextBlock _header;
 23	
 24	    public SpritePreviewWindow(
 25	        SpriteSheet sheet,
 26	        byte[] sourceBytes,
 27	        string suggestedName,
 28	        I18nService? i18n = null)
 29	    {
 30	        var localization = i18n ?? new I18nService();
 31	        _i18n = localization;
 32	        _sheet = sheet;
 33	        _sourceBytes = sourceBytes;
 34	        _suggestedName = suggestedName;
 35	
 36	        Title = "切片预览 — DesktopPet";
 37	        Width = 620;
 38	        Height = 480;
 39	        WindowStartupLocation = WindowStartupLocation.CenterOwner;
 40	        ResizeMode = ResizeMode.NoResize;
 41	        Background = (Brush)Application.Current.FindResource("WindowBgBrush");
 42	
 43	        var root = new StackPanel { Margin = new Thickness(16) };
 44	
 45	        var header = new TextBlock
 46	        {
 47	            FontSize = 14,
 48	            FontWeight = FontWeights.SemiBold,
 49	            Margin = new Thickness(0, 0, 0, 10),
 50	        };
 51	        _header = header;
 52	        WpfLocalizer.SetFormattedText(
 53	            header,
 54	            "{0} — 检测到 {1} 行动画",
 55	            _i18n,
 56	            suggestedName,
 57	            sheet.Clips.Count);
 58	        root.Children.Add(header);
 59	
 60	        // 原图 + 网格线覆盖。修复：曾误用压缩文件字节（_sourceBytes）当像素缓冲，
 61	        // 缓冲不足抛异常（async void 调用链无 handler → 进程崩溃）或显示垃圾像素；
 62	        // 现在用 Decode 保留的解码 RGBA 构建（Core 输出 RGBA，WPF 需 BGRA）。
 63	        var imageArea = new Grid { Width = 384, Height = 320, HorizontalAlignment = HorizontalAlignment.Center };
 64	        var source = BuildSourcePreview(sheet);
 65	        var image = new Image { Source = source, Stretch = Stretch.Uniform, Width = 384, Height = 320 };
 66	        imageArea.Children.Add(image);
 67	
 68	        var overlay = new Canvas { Width = 384, Height = 320 };
 69	        var scaleX = 384.0 / sheet.SourceWidth;
 70	        var scaleY = 320.0 / sheet.SourceHeight;
 71	        foreach (var clip in sheet.Clips)
 72	        {
 73	            foreach (var frame in clip)
 74	            {
 75	                var rect = new System.Windows.Shapes.Rectangle
 76	                {
 77	                    Width = frame.Width * scaleX,
 78	                    Height = frame.Height * scaleY,
 79	                    Stroke = new SolidColorBrush(Color.FromRgb(0xFF, 0x8A, 0x65)),
 80	                    StrokeThickness = 1,
 81	                    StrokeDashArray = [3, 2],
 82	                };
 83	                Canvas.SetLeft(rect, frame.RectX * scaleX);
 84	                Canvas.SetTop(rect, frame.RectY * scaleY);
 85	                overlay.Children.Add(rect);
 86	            }
 87	        }
 88	        imageArea.Children.Add(overlay);
 89	        root.Children.Add(imageArea);
 90	
 91	        // 帧条：每行首帧缩略图
 92	        var frameStrip = new WrapPanel { Margin = new Thickness(0, 12, 0, 0), MaxWidth = 600 };
 93	        foreach (var clip in _sheet.Clips)
 94	        {
 95	            if (clip.Count == 0) continue;
 96	            var frame = clip[0];
 97	            var thumb = new Image
 98	            {
 99	                Source = FrameToBitmap(frame),
100	                Width = 56,
101	                Height = 56 * frame.Height / (double)frame.Width,
102	                Stretch = Stretch.Uniform,
103	                Margin = new Thickness(2),
104	                SnapsToDevicePixels = true,
105	            };
106	            RenderOptions.SetBitmapScalingMode(thumb, BitmapScalingMode.NearestNeighbor);
107	            frameStrip.Children.Add(thumb);
108	        }
109	        root.Children.Add(frameStrip);
110	
111	        // 操作按钮
112	        var buttons = new StackPanel
113	        {
114	            Orientation = Orientation.Horizontal,
115	            HorizontalAlignment = HorizontalAlignment.Right,
116	            Margin = new Thickness(0, 14, 0, 0),
117	        };
118	        var cancel = new Button { Content = "取消", Width = 80, Margin = new Thickness(0, 0, 8, 0), Padding = new Thickness(4) };
119	        cancel.Click += (_, _) => { DialogResult = false; };
120	        var confirm = new Button
121	        {
122	            Content = "导入此宠物",
123	            Width = 110,
124	            Padding = new Thickness(4),
125	            IsDefault = true,
126	            Style = (Style)Application.Current.FindResource("ButtonPrimaryStyle"),
127	        };
128	        confirm.Click += (_, _) => { DialogResult = true; };
129	        buttons.Children.Add(cancel);
130	        buttons.Children.Add(confirm);
131	        root.Children.Add(buttons);
132	
133	        Content = root;
134	        WpfLocalizer.ApplyNew(this, _i18n);
135	    }
136	
137	    public void ApplyLocalization(I18nService i18n)
138	    {
139	        _i18n = i18n;
140	        WpfLocalizer.RefreshTracked(this, i18n);
141	    }
142	
143	    /// <summary>导入时由 PetWindow 读取：原始文件字节 + 建议名。</summary>
144	    public (byte[] Bytes, string Name) ImportPayload => (_sourceBytes, _suggestedName);
145	
146	    /// <summary>解码源图位图（Bgra32）。SourceRgba 缺失时回退透明图（不崩）。</summary>
147	    private static BitmapSource BuildSourcePreview(SpriteSheet sheet)
148	    {
149	        if (sheet.SourceRgba is { Length: > 0 } rgba)
150	        {
151	            var pixels = RgbaToBgra(rgba);
152	            return BitmapSource.Create(
153	                sheet.SourceWidth, sheet.SourceHeight, 96, 96, PixelFormats.Bgra32, null,
154	                pixels, sheet.SourceWidth * 4);
155	        }
156	        return BitmapSource.Create(
157	            sheet.SourceWidth, sheet.SourceHeight, 96, 96, PixelFormats.Bgra32, null,
158	            new byte[sheet.SourceWidth * sheet.SourceHeight * 4], sheet.SourceWidth * 4);
159	    }
160	
161	    private static byte[] RgbaToBgra(byte[] rgba)
162	    {
163	        var bgra = new byte[rgba.Length];
164	        for (var i = 0; i < rgba.Length; i += 4)
165	        {
166	            bgra[i] = rgba[i + 2];
167	            bgra[i + 1] = rgba[i + 1];
168	            bgra[i + 2] = rgba[i];
169	            bgra[i + 3] = rgba[i + 3];
170	        }
171	        return bgra;
172	    }
173	
174	    private static BitmapSource FrameToBitmap(SpriteFrame frame)
175	        => BitmapSource.Create(
176	            frame.Width, frame.Height, 96, 96, PixelFormats.Bgra32, null,
177	            RgbaToBgra(frame.Rgba), frame.Width * 4);
178	}
  1	using System.Runtime.InteropServices;
  2	using System.Windows;
  3	using System.Windows.Interop;
  4	using System.Windows.Threading;
  5	using DesktopPet.App.Localization;
  6	using DesktopPet.Core.Danmaku;
  7	using DesktopPet.Core.I18n;
  8	using Microsoft.Graphics.Canvas;
  9	using Microsoft.Graphics.Canvas.Text;
 10	using Microsoft.Graphics.Canvas.UI.Xaml;
 11	
 12	// CS8305：CanvasAnimatedControl 被 Win2D 标记为实验性（evaluation only）。
 13	// PoC 已验证其在 WPF XAML Island 中工作正常（透明窗口 + GPU 渲染 + Paused 停转），
 14	// 且自带渲染循环优于 CanvasControl + 外部驱动，故定点抑制。
 15	#pragma warning disable CS8305
 16	
 17	namespace DesktopPet.App.Windows;
 18	
 19	/// <summary>
 20	/// 弹幕层（迁移计划 §6.5 / 验收：60fps）：独立全屏透明置顶窗口，
 21	/// IsHitTestVisible=false + WS_EX_TRANSPARENT 点击穿透；Win2D GPU 合成滚动文本。
 22	/// 无弹幕时暂停渲染循环（CPU 归零）；帧计数暴露给验收冒烟。
 23	/// 模式切换即销毁（ModeService 管理生命周期）。
 24	/// </summary>
 25	public sealed class DanmakuWindow : Window
 26	{
 27	    private readonly DanmakuEngine _engine;
 28	    private readonly double _trackHeight;
 29	    private readonly CanvasTextFormat _textFormat = new()
 30	    {
 31	        FontSize = 30,
 32	        FontFamily = "Microsoft YaHei UI",
 33	        WordWrapping = CanvasWordWrapping.NoWrap,
 34	    };
 35	    private XamlIslandHost? _island;
 36	    private CanvasAnimatedControl? _canvas;
 37	    private long _frameCount;
 38	    private readonly DispatcherTimer _fpsTimer = new() { Interval = TimeSpan.FromSeconds(1) };
 39	    private I18nService _i18n;
 40	    private double _fps;
 41	
 42	    /// <summary>最近 1s 帧率（验收 60fps 采样）。</summary>
 43	    public double Fps => _fps;
 44	
 45	    public DanmakuWindow(
 46	        double width,
 47	        double height,
 48	        int trackCount = 10,
 49	        I18nService? i18n = null)
 50	    {
 51	        _i18n = i18n ?? new I18nService();
 52	        Title = _i18n.T("DesktopPet Danmaku");
 53	        WindowStyle = WindowStyle.None;
 54	        AllowsTransparency = true;
 55	        Background = System.Windows.Media.Brushes.Transparent;
 56	        Topmost = true;
 57	        ShowInTaskbar = false;
 58	        Left = 0;
 59	        Top = 0;
 60	        Width = width;
 61	        Height = height;
 62	        _engine = new DanmakuEngine(width, trackCount, minSpeed: 220, maxSpeed: 420, minGap: 220);
 63	        _trackHeight = height / Math.Max(1, trackCount);
 64	
 65	        _island = new XamlIslandHost(BuildCanvas);
 66	        Content = _island;
 67	        WpfLocalizer.ApplyNew(this, _i18n);
 68	        // XAML Island 必须在窗口稳定（Loaded）后 Attach（Show 中途初始化报窗口线程归属错误）
 69	        Loaded += (_, _) =>
 70	        {
 71	            EnsureWinUiInitialized(); // 必须先于 DesktopWindowXamlSource 创建
 72	            _island.AttachAndInitialize();
 73	            _fpsTimer.Tick -= OnFpsTimerTick;
 74	            _fpsTimer.Tick += OnFpsTimerTick;
 75	            _fpsTimer.Start();
 76	        };
 77	    }
 78	
 79	    private static bool _winuiInitialized;
 80	    private static readonly object WinUiInitLock = new();
 81	
 82	    /// <summary>WinAppSDK 初始化（DispatcherQueue + XAML manager；每线程一次）。</summary>
 83	    private static void EnsureWinUiInitialized()
 84	    {
 85	        if (_winuiInitialized) return;
 86	        lock (WinUiInitLock)
 87	        {
 88	            if (_winuiInitialized) return;
 89	            _ = Microsoft.UI.Dispatching.DispatcherQueueController.CreateOnCurrentThread();
 90	            _ = Microsoft.UI.Xaml.Hosting.WindowsXamlManager.InitializeForCurrentThread();
 91	            _winuiInitialized = true;
 92	        }
 93	    }
 94	
 95	    public void ApplyLocalization(I18nService i18n)
 96	    {
 97	        _i18n = i18n;
 98	        WpfLocalizer.RefreshTracked(this, i18n);
 99	    }
100	
101	    protected override void OnSourceInitialized(EventArgs e)
102	    {
103	        base.OnSourceInitialized(e);
104	        // 点击穿透：透明 + 不激活（不挡鼠标、不抢焦点）
105	        var hwnd = new WindowInteropHelper(this).Handle;
106	        var exStyle = GetWindowLongPtr(hwnd, -20 /* GWL_EXSTYLE */);
107	        SetWindowLongPtr(hwnd, -20, exStyle | 0x00000020 /* WS_EX_TRANSPARENT */ | 0x08000000 /* WS_EX_NOACTIVATE */);
108	    }
109	
110	    private Microsoft.UI.Xaml.UIElement BuildCanvas()
111	    {
112	        var grid = new Microsoft.UI.Xaml.Controls.Grid
113	        {
114	            Background = new Microsoft.UI.Xaml.Media.SolidColorBrush(global::Windows.UI.Color.FromArgb(0, 0, 0, 0)),
115	        };
116	        _canvas = new CanvasAnimatedControl
117	        {
118	            Width = (float)ActualWidth,
119	            Height = (float)ActualHeight,
120	            Paused = true, // 无弹幕不渲染（CPU 归零）
121	        };
122	        _canvas.Update += (_, args) =>
123	        {
124	            if (!_canvas.Paused
125	                && !_engine.Tick(args.Timing.ElapsedTime.TotalSeconds))
126	            {
127	                _canvas.Paused = true;
128	            }
129	        };
130	        _canvas.Draw += (_, args) =>
131	        {
132	            args.DrawingSession.Clear(global::Windows.UI.Color.FromArgb(0, 0, 0, 0));
133	            var ds = args.DrawingSession;
134	            foreach (var item in _engine.Active)
135	            {
136	                ds.DrawText(item.Text, (float)item.X, (float)(item.Track * _trackHeight),
137	                    global::Microsoft.UI.Colors.White, _textFormat);
138	            }
139	            _frameCount++;
140	        };
141	        grid.Children.Add(_canvas);
142	        return grid;
143	    }
144	
145	    /// <summary>推送一条弹幕（事件驱动；唤醒渲染循环）。</summary>
146	    public void ShowDanmaku(string text)
147	    {
148	        if (_engine.Enqueue(text, DateTime.Now) is not null && _canvas is not null)
149	        {
150	            _canvas.Paused = false;
151	        }
152	    }
153	
154	    private void OnFpsTimerTick(object? sender, EventArgs e)
155	    {
156	        _fps = _frameCount;
157	        _frameCount = 0;
158	    }
159	
160	    protected override void OnClosed(EventArgs e)
161	    {
162	        _fpsTimer.Stop();
163	        _fpsTimer.Tick -= OnFpsTimerTick;
164	        var canvas = _canvas;
165	        _canvas = null;
166	        if (canvas is not null)
167	        {
168	            canvas.Paused = true;
169	            canvas.RemoveFromVisualTree();
170	        }
171	        _engine.Clear();
172	        _textFormat.Dispose();
173	        _island?.DetachAndDispose();
174	        _island = null;
175	        base.OnClosed(e);
176	    }
177	
178	    [DllImport("user32.dll", EntryPoint = "GetWindowLongPtr")]
179	    private static extern IntPtr GetWindowLongPtr(IntPtr hwnd, int index);
180	
181	    [DllImport("user32.dll", EntryPoint = "SetWindowLongPtr")]
182	    private static extern IntPtr SetWindowLongPtr(IntPtr hwnd, int index, IntPtr newStyle);
183	}

