 10	namespace DesktopPet.App.Windows;
 11	
 12	/// <summary>
 13	/// 导入切片预览（对齐 settings.html 的切片预览交互，最小版）：
 14	/// 原图 + 切片网格线覆盖 + 帧条（每行首帧缩略图），确认后导入。
 15	/// </summary>
 16	public sealed class SpritePreviewWindow : Window
 17	{
 18	    private readonly SpriteSheet _sheet;
 19	    private readonly byte[] _sourceBytes;
 20	    private readonly string _suggestedName;
 21	    private I18nService _i18n;
 22	    private readonly TextBlock _header;
 23	
 24	    public SpritePreviewWindow(
 25	        SpriteSheet sheet,
 26	        byte[] sourceBytes,
 27	        string suggestedName,
 28	        I18nService? i18n = null)
 29	    {
 30	        var localization = i18n ?? new I18nService();
 31	        _i18n = localization;
 32	        _sheet = sheet;
 33	        _sourceBytes = sourceBytes;
 34	        _suggestedName = suggestedName;
 35	
 36	        Title = "切片预览 — DesktopPet";
 37	        Width = 620;
 38	        Height = 480;
 39	        WindowStartupLocation = WindowStartupLocation.CenterOwner;
 40	        ResizeMode = ResizeMode.NoResize;
 41	        Background = (Brush)Application.Current.FindResource("WindowBgBrush");
 42	
 43	        var root = new StackPanel { Margin = new Thickness(16) };
 44	
 45	        var header = new TextBlock
 46	        {
 47	            FontSize = 14,
 48	            FontWeight = FontWeights.SemiBold,
 49	            Margin = new Thickness(0, 0, 0, 10),
 50	        };
 51	        _header = header;
 52	        WpfLocalizer.SetFormattedText(
 53	            header,
 54	            "{0} — 检测到 {1} 行动画",
 55	            _i18n,
 56	            suggestedName,
 57	            sheet.Clips.Count);
 58	        root.Children.Add(header);
 59	
 60	        // 原图 + 网格线覆盖。修复：曾误用压缩文件字节（_sourceBytes）当像素缓冲，
 61	        // 缓冲不足抛异常（async void 调用链无 handler → 进程崩溃）或显示垃圾像素；
 62	        // 现在用 Decode 保留的解码 RGBA 构建（Core 输出 RGBA，WPF 需 BGRA）。
 63	        var imageArea = new Grid { Width = 384, Height = 320, HorizontalAlignment = HorizontalAlignment.Center };
 64	        var source = BuildSourcePreview(sheet);
 65	        var image = new Image { Source = source, Stretch = Stretch.Uniform, Width = 384, Height = 320 };
 66	        imageArea.Children.Add(image);
 67	
 68	        var overlay = new Canvas { Width = 384, Height = 320 };
 69	        var scaleX = 384.0 / sheet.SourceWidth;
 70	        var scaleY = 320.0 / sheet.SourceHeight;
 71	        foreach (var clip in sheet.Clips)
 72	        {
 73	            foreach (var frame in clip)
 74	            {
 75	                var rect = new System.Windows.Shapes.Rectangle
 76	                {
 77	                    Width = frame.Width * scaleX,
 78	                    Height = frame.Height * scaleY,
 79	                    Stroke = new SolidColorBrush(Color.FromRgb(0xFF, 0x8A, 0x65)),
 80	                    StrokeThickness = 1,
 81	                    StrokeDashArray = [3, 2],
 82	                };
 83	                Canvas.SetLeft(rect, frame.RectX * scaleX);
 84	                Canvas.SetTop(rect, frame.RectY * scaleY);
 85	                overlay.Children.Add(rect);
 86	            }
 87	        }
 88	        imageArea.Children.Add(overlay);
 89	        root.Children.Add(imageArea);
 90	
 91	        // 帧条：每行首帧缩略图
 92	        var frameStrip = new WrapPanel { Margin = new Thickness(0, 12, 0, 0), MaxWidth = 600 };
 93	        foreach (var clip in _sheet.Clips)
 94	        {
 95	            if (clip.Count == 0) continue;
 96	            var frame = clip[0];
 97	            var thumb = new Image
 98	            {
 99	                Source = FrameToBitmap(frame),
100	                Width = 56,
101	                Height = 56 * frame.Height / (double)frame.Width,
102	                Stretch = Stretch.Uniform,
103	                Margin = new Thickness(2),
104	                SnapsToDevicePixels = true,
105	            };
106	            RenderOptions.SetBitmapScalingMode(thumb, BitmapScalingMode.NearestNeighbor);
107	            frameStrip.Children.Add(thumb);
108	        }
109	        root.Children.Add(frameStrip);
110	
111	        // 操作按钮
112	        var buttons = new StackPanel
113	        {
114	            Orientation = Orientation.Horizontal,
115	            HorizontalAlignment = HorizontalAlignment.Right,
116	            Margin = new Thickness(0, 14, 0, 0),
117	        };
118	        var cancel = new Button { Content = "取消", Width = 80, Margin = new Thickness(0, 0, 8, 0), Padding = new Thickness(4) };
119	        cancel.Click += (_, _) => { DialogResult = false; };
120	        var confirm = new Button
121	        {
122	            Content = "导入此宠物",
123	            Width = 110,
124	            Padding = new Thickness(4),
125	            IsDefault = true,
126	            Style = (Style)Application.Current.FindResource("ButtonPrimaryStyle"),
127	        };
128	        confirm.Click += (_, _) => { DialogResult = true; };
129	        buttons.Children.Add(cancel);
130	        buttons.Children.Add(confirm);
131	        root.Children.Add(buttons);
132	
133	        Content = root;
134	        WpfLocalizer.ApplyNew(this, _i18n);
135	    }
