 19	
 20	    public TrayController(PetWindowManager manager, I18nService? i18n = null)
 21	    {
 22	        _icon = new TaskbarIcon
 23	        {
 24	            Icon = CreateIcon(),
 25	            ToolTipText = "DesktopPet",
 26	        };
