 28	        _toggleItem = new MenuItem { Header = "显示/隐藏宠物", IsCheckable = true, IsChecked = manager.GloballyVisible };
 29	        _toggleItem.Click += (_, _) => manager.SetGlobalVisible(_toggleItem.IsChecked);
 30	
 31	        var settingsItem = new MenuItem { Header = "设置" };
 32	        settingsItem.Click += (_, _) => manager.OpenSettings();
 33	
 34	        var quitItem = new MenuItem { Header = "退出" };
 35	        quitItem.Click += (_, _) => Application.Current.Shutdown();
 36	
 37	        var menu = new ContextMenu();
 38	        menu.Items.Add(settingsItem);
 39	        menu.Items.Add(new Separator());
 40	        menu.Items.Add(_toggleItem);
 41	        menu.Items.Add(new Separator());
 42	        menu.Items.Add(quitItem);
 43	        _menu = menu;
 44	        _icon.ContextMenu = menu;
 45	        WpfLocalizer.ApplyNew(menu, i18n ?? new I18nService());
 46	
 47	        manager.GlobalVisibilityChanged += OnGlobalVisibilityChanged;
 48	    }
