 59	    /// <summary>程序生成的像素猫头托盘图标（H.NotifyIcon 需要 System.Drawing.Icon）。</summary>
 60	    private static System.Drawing.Icon CreateIcon()
 61	    {
 62	        using var bitmap = new System.Drawing.Bitmap(32, 32);
 63	        using (var g = System.Drawing.Graphics.FromImage(bitmap))
 64	        {
 65	            g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
 66	            using var head = new System.Drawing.SolidBrush(System.Drawing.Color.FromArgb(0x5B, 0x8D, 0xE0));
 67	            g.FillEllipse(head, 2, 2, 28, 28);
 68	            using var eye = new System.Drawing.SolidBrush(System.Drawing.Color.White);
 69	            g.FillEllipse(eye, 9, 10, 5, 7);
 70	            g.FillEllipse(eye, 19, 10, 5, 7);
 71	        }
 72	        var handle = bitmap.GetHicon();
 73	        using var fromHandle = System.Drawing.Icon.FromHandle(handle);
 74	        return (System.Drawing.Icon)fromHandle.Clone(); // 独立句柄，可安全 Dispose
 75	    }
 76	
 77	    public void Dispose()
 78	    {
 79	        _icon.Dispose();
 80	    }
