 68	            using var eye = new System.Drawing.SolidBrush(System.Drawing.Color.White);
 69	            g.FillEllipse(eye, 9, 10, 5, 7);
 70	            g.FillEllipse(eye, 19, 10, 5, 7);
 71	        }
 72	        var handle = bitmap.GetHicon();
 73	        using var fromHandle = System.Drawing.Icon.FromHandle(handle);
