2439	        var next = AppSettings.Normalize(change(before));
2440	        // 首次开启 AI → 引导窗（称呼+人格）；完成标记随本 Save 一并落盘
2441	        var onboardingRequired = false;
2442	        var onboardingCompleted = false;
2443	        if (next.Ai.Enabled && !before.Ai.Enabled && !next.Ai.Onboarded)
