2472	                    },
2473	                    i18n: _i18n);
2474	                welcome.Owner = this;
2475	                welcome.ShowDialog();
2476	            }
2477	        }
2478	        if (onboardingRequired && !onboardingCompleted)
2479	            return;
2480	        if (onboardingCompleted)
