   1	using System.Runtime.CompilerServices;
   2	using System.Windows;
   3	using System.Windows.Automation;
   4	using System.Windows.Controls;
   5	using DesktopPet.Core.I18n;
   6	
   7	namespace DesktopPet.App.Localization;
   8	
   9	/// <summary>
  10	/// Tracks static WPF strings on first discovery, then refreshes only those tracked slots.
  11	/// Dynamic user/model content created later is never discovered during a language refresh.
  12	/// </summary>
  13	public static class WpfLocalizer
  14	{
  15	    public sealed record LocalizedArgument(string Key);
  16	
  17	    private sealed class Entry
  18	    {
  19	        public string? Title;
  20	        public string? Text;
  21	        public object?[]? TextArguments;
  22	        public string? Content;
  23	        public object?[]? ContentArguments;
  24	        public string? Header;
  25	        public string? ToolTip;
  26	        public object?[]? ToolTipArguments;
  27	        public string? AutomationName;
  28	        public object?[]? AutomationArguments;
  29	    }
  30	
  31	    private static readonly ConditionalWeakTable<DependencyObject, Entry> Entries = new();
  32	    private static readonly ConditionalWeakTable<DependencyObject, object> Exclusions = new();
  33	
  34	    public static void ApplyNew(DependencyObject root, I18nService i18n)
  35	        => Apply(root, i18n, discover: true, new HashSet<DependencyObject>());
  36	
  37	    public static void RefreshTracked(DependencyObject root, I18nService i18n)
  38	        => Apply(root, i18n, discover: false, new HashSet<DependencyObject>());
  39	
  40	    public static LocalizedArgument Localize(string key) => new(key);
  41	
  42	    public static void Exclude(DependencyObject element)
  43	    {
  44	        Entries.Remove(element);
  45	        _ = Exclusions.GetValue(element, _ => new object());
  46	    }
  47	
  48	    public static void SetDynamicText(TextBlock block, string text)
  49	    {
  50	        Exclude(block);
  51	        block.Text = text;
  52	    }
  53	
  54	    public static void SetDynamicContent(ContentControl control, object? content)
  55	    {
  56	        Exclude(control);
  57	        control.Content = content;
  58	    }
  59	
  60	    public static void SetText(TextBlock block, string key, I18nService i18n)
  61	    {
  62	        var entry = Entries.GetOrCreateValue(block);
  63	        entry.Text = key;
  64	        entry.TextArguments = null;
  65	        block.Text = i18n.T(key);
  66	    }
  67	
  68	    public static void SetFormattedText(
  69	        TextBlock block,
  70	        string template,
  71	        I18nService i18n,
  72	        params object?[] args)
  73	    {
  74	        var entry = Entries.GetOrCreateValue(block);
  75	        entry.Text = template;
  76	        entry.TextArguments = args.ToArray();
  77	        block.Text = i18n.Format(template, ResolveArguments(i18n, args));
  78	    }
  79	
  80	    public static void SetFormattedContent(
  81	        ContentControl control,
  82	        string template,
  83	        I18nService i18n,
  84	        params object?[] args)
  85	    {
  86	        var entry = Entries.GetOrCreateValue(control);
  87	        entry.Content = template;
  88	        entry.ContentArguments = args.ToArray();
  89	        control.Content = i18n.Format(template, ResolveArguments(i18n, args));
  90	    }
  91	
  92	    public static void SetFormattedToolTip(
  93	        FrameworkElement element,
  94	        string template,
  95	        I18nService i18n,
  96	        params object?[] args)
  97	    {
  98	        var entry = Entries.GetOrCreateValue(element);
  99	        entry.ToolTip = template;
 100	        entry.ToolTipArguments = args.ToArray();
 101	        element.ToolTip = i18n.Format(template, ResolveArguments(i18n, args));
 102	    }
 103	
 104	    public static void SetFormattedAutomationName(
 105	        DependencyObject element,
 106	        string template,
 107	        I18nService i18n,
 108	        params object?[] args)
 109	    {
 110	        var entry = Entries.GetOrCreateValue(element);
 111	        entry.AutomationName = template;
 112	        entry.AutomationArguments = args.ToArray();
 113	        AutomationProperties.SetName(element, i18n.Format(template, ResolveArguments(i18n, args)));
 114	    }
 115	
 116	    private static void Apply(
 117	        DependencyObject current,
 118	        I18nService i18n,
 119	        bool discover,
 120	        HashSet<DependencyObject> visited)
 121	    {
 122	        if (!visited.Add(current)) return;
 123	        if (discover) Discover(current);
 124	        if (Entries.TryGetValue(current, out var entry)) Translate(current, entry, i18n);
 125	
 126	        foreach (var child in LogicalTreeHelper.GetChildren(current))
 127	        {
 128	            if (child is DependencyObject dependency)
 129	                Apply(dependency, i18n, discover, visited);
 130	        }
 131	    }
 132	
 133	    private static void Discover(DependencyObject current)
 134	    {
 135	        if (Exclusions.TryGetValue(current, out _)) return;
 136	        Entry? entry = null;
 137	        if (current is Window window && IsCatalogText(window.Title))
 138	            (entry ??= Entries.GetOrCreateValue(current)).Title = window.Title;
 139	        if (current is TextBlock textBlock && IsCatalogText(textBlock.Text))
 140	            (entry ??= Entries.GetOrCreateValue(current)).Text = textBlock.Text;
 141	        if (current is ContentControl contentControl
 142	            && contentControl.Content is string content
 143	            && IsCatalogText(content))
 144	        {
 145	            (entry ??= Entries.GetOrCreateValue(current)).Content = content;
 146	        }
 147	        if (current is HeaderedItemsControl headered
 148	            && headered.Header is string header
 149	            && IsCatalogText(header))
 150	        {
 151	            (entry ??= Entries.GetOrCreateValue(current)).Header = header;
 152	        }
 153	        if (current is FrameworkElement automationElement
 154	            && AutomationProperties.GetName(automationElement) is { Length: > 0 } automationName
 155	            && IsCatalogText(automationName))
 156	        {
 157	            (entry ??= Entries.GetOrCreateValue(current)).AutomationName = automationName;
 158	        }
 159	        if (current is FrameworkElement element
 160	            && element.ToolTip is string toolTip
 161	            && IsCatalogText(toolTip))
 162	        {
 163	            (entry ??= Entries.GetOrCreateValue(current)).ToolTip = toolTip;
 164	        }
 165	    }
 166	
 167	    private static void Translate(DependencyObject current, Entry entry, I18nService i18n)
 168	    {
 169	        if (current is Window window && entry.Title is not null)
 170	            window.Title = i18n.T(entry.Title);
 171	        if (current is TextBlock textBlock && entry.Text is not null)
 172	            textBlock.Text = entry.TextArguments is { } textArgs
 173	                ? i18n.Format(entry.Text, ResolveArguments(i18n, textArgs))
 174	                : i18n.T(entry.Text);
 175	        if (current is ContentControl contentControl && entry.Content is not null)
 176	            contentControl.Content = entry.ContentArguments is { } contentArgs
 177	                ? i18n.Format(entry.Content, ResolveArguments(i18n, contentArgs))
 178	                : i18n.T(entry.Content);
 179	        if (current is HeaderedItemsControl headered && entry.Header is not null)
 180	            headered.Header = i18n.T(entry.Header);
 181	        if (current is FrameworkElement element && entry.ToolTip is not null)
 182	            element.ToolTip = entry.ToolTipArguments is { } toolTipArgs
 183	                ? i18n.Format(entry.ToolTip, ResolveArguments(i18n, toolTipArgs))
 184	                : i18n.T(entry.ToolTip);
 185	        if (current is DependencyObject automationElement && entry.AutomationName is not null)
 186	            AutomationProperties.SetName(
 187	                automationElement,
 188	                entry.AutomationArguments is { } automationArgs
 189	                    ? i18n.Format(entry.AutomationName, ResolveArguments(i18n, automationArgs))
 190	                    : i18n.T(entry.AutomationName));
 191	    }
 192	
 193	    private static object?[] ResolveArguments(I18nService i18n, object?[] args)
 194	        => args.Select(argument => argument is LocalizedArgument localized
 195	            ? i18n.T(localized.Key)
 196	            : argument).ToArray();
 197	
 198	    private static bool IsCatalogText(string? text)
 199	        => !string.IsNullOrWhiteSpace(text)
 200	           && I18nService.HasTranslation(AppLang.En, text);
 201	}
2000	    private UIElement BuildAiPage()
2001	    {
2002	        var stack = new StackPanel();
2003	        var ai = _settings.Ai;
2004	        var personas = _ai?.Personas ?? new Core.Personas.PersonasFileModel();
2005	
2006	        // AI 总开关
2007	        var masterToggle = new CheckBox
2008	        {
2009	            Content = "启用 AI",
2010	            Style = AppStyle("ToggleSwitchStyle"),
2011	            FontSize = 14,
2012	            FontWeight = FontWeights.SemiBold,
2013	            IsChecked = ai.Enabled,
2014	        };
2015	        masterToggle.Click += (_, _) =>
2016	            Save(s => s with { Ai = s.Ai with { Enabled = masterToggle.IsChecked == true } });
